INSERT INTO `movies` (`id`, `title`, `slug`, `description`, `director`, `cast`, `duration_min`, `release_date`, `end_date`, `poster`, `banner`, `trailer_url`, `age_rating`, `status`, `language`, `subtitle`, `country`) VALUES
(1, 'Song Hỷ Lâm Nguy', 'song-hy-lam-nguy', 'Hai lễ cưới, một sang trọng sa hoa, một đạm bạc dân dã, đáng lý sẽ được tổ chức đối diện nhau. Rắc rối bắt đầu khi đội ngũ tổ chức của hai lễ cưới phát hiện ra danh sách khách mời của hai bên là giống nhau.', 'Vũ Hà', 'MisThy, Dustin Nguyễn, Jun Vũ, Hoàng Phi, Trung Anh', 113, '2026-04-03', NULL, 'tmdb_poster_dbfbe3f55936200f1588f0a4d9f9185e.jpg', 'tmdb_banner_4a0c8be4bf7473f2ef486df465961e92.jpg', 'https://www.youtube.com/watch?v=hJpfrsQtJlM', 'C13', 'now_showing', 'Tieng Viet', NULL, NULL),
(2, 'Hẹn Em Ngày Nhật Thực', 'hen-em-ngay-nhat-thuc', 'Hẹn Em Ngày Nhật Thực', 'Lê Thiện Viễn', 'Khương Lê, Đoàn Thiên Ân, Thanh Sơn, Hứa Vĩ Văn, Lê Khanh', 118, '2026-04-03', NULL, 'tmdb_poster_d00c2af117724bffb281642cf4af9311.jpg', 'tmdb_banner_0e505c14138f7f856fa112d29212d272.jpg', NULL, 'C13', 'now_showing', 'Tieng Viet', NULL, 'Viet Nam'),
(3, 'Ánh Dương Của Mẹ', 'anh-duong-cua-me', 'Trong không gian ngột ngạt của một nhà tù nữ, một mầm sống mới đã nảy mầm: một bé gái chào đời giữa tiếng hát mừng sinh nhật và vòng tay của bốn nữ tù nhân. Mỗi người phụ nữ ấy đều mang một bản án và một quá khứ đầy vết sẹo, nhưng sự xuất hiện của đứa trẻ đã trở thành tia sáng duy nhất sưởi ấm tâm hồn họ. Mọi chuyện trở nên xáo trộn khi một tù nhân mới đầy nổi loạn gia nhập nhóm. Từ những va chạm, mâu thuẫn nảy lửa ban đầu, sự hiện diện ngây thơ của bé gái đã dần xóa tan khoảng cách, biến những con người xa lạ thành một gia đình đặc biệt. Hạnh phúc ngắn chẳng được bao lâu khi đứa trẻ được chẩn đoán mắc một căn bệnh hiểm nghèo về mắt, đe dọa sẽ lấy đi ánh sáng vĩnh viễn. Để dành tặng em một kỷ niệm cuối cùng thật trọn vẹn, những người mẹ "không cùng huyết thống" đã quyết định thành lập một dàn đồng ca ngay sau song sắt.', '林孝謙', '陳意涵, ジュディ・オング, Chung Hân Lăng, 孫淑媚, 苗可麗', 135, '2026-04-03', NULL, 'tmdb_poster_d99c9508592a2e65a431e6e207a42c0c.jpg', 'tmdb_banner_f50d36e6cbcb0455442a2492e531cd6b.jpg', NULL, 'C13', 'now_showing', 'Tieng Trung', 'Phu de Viet', 'Taiwan'),
(4, 'Phi Vụ Cuối Cùng', 'phi-vu-cuoi-cung', 'Petch là một tay súng đánh thuê, người đã dành phần lớn cuộc đời sống giữa thế giới bạo lực, nơi những phi vụ đẫm máu diễn ra như một phần công việc thường nhật. Sau nhiều năm lún sâu vào tội lỗi, Petch bắt đầu khao khát rời bỏ con đường cũ để tìm lại tự do và một cuộc sống bình thường. Thế nhưng quá khứ không dễ dàng buông tha anh. Khi những người thân cận bị cuốn vào cuộc thanh trừng giữa các băng nhóm, Petch buộc phải quay lại thế giới mà anh từng cố gắng trốn chạy. Anh chấp nhận thực hiện một nhiệm vụ cuối cùng đầy nguy hiểm, với hy vọng có thể xóa bỏ mọi ân oán trong quá khứ. Nhưng cũng từ đây, Petch bị đẩy vào cuộc đối đầu nghẹt thở với những thế lực từng tạo nên anh. Trong trận chiến sinh tử ấy, mỗi viên đạn đều mang theo cái giá phải trả, và chỉ một sai lầm cũng có thể khiến anh đánh đổi bằng chính mạng sống của mình.', 'พุฒิพงษ์ นาคทอง', 'สมพล รุ่งพาณิชย์, ภัทร เอกแสงกุล, ษริกา สารทศิลป์ศุภา, Benjamin Joseph Varney, อรรถกร บุญเพ็ง', 113, '2026-04-03', NULL, 'tmdb_poster_bba4f50d4a7f4f77a63b8b64ea1ce8eb.jpg', 'tmdb_banner_5c56530fb3fc38938490ad5ea1f7cb9f.jpg', 'https://www.youtube.com/watch?v=3v1Eo7CVE8s', 'C13', 'now_showing', 'Tieng Thai', 'Phu de Viet', 'Thai Lan'),
(5, 'Trò Chơi Của Quỷ 2', 'tro-choi-cua-quy-2', 'Chỉ ít phút sau khi sống sót khỏi cuộc tấn công toàn diện của gia tộc Le Domas, Grace nhận ra mình đã bước sang cấp độ tiếp theo của trò chơi ác mộng — lần này, với người chị em xa cách Faith đứng bên cạnh. Grace chỉ có một cơ hội để sống sót, bảo vệ em gái, và giành lấy Ngai Cao của Hội Đồng — thế lực đang kiểm soát cả thế giới. Bốn gia tộc đối địch đang truy lùng cô để đoạt lấy ngai vàng, và kẻ chiến thắng sẽ thống trị tất cả.', 'Matt Bettinelli-Olpin', 'Samara Weaving, Kathryn Newton, Elijah Wood, Sarah Michelle Gellar, Shawn Hatosy', 108, '2026-04-03', NULL, 'tmdb_poster_2bc429811eb34bd5ccb871fad58b9589.jpg', 'tmdb_banner_ebb1775822b3f75b84736cbf3b961305.jpg', NULL, 'C16', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(6, 'Phim Super Mario Thiên Hà', 'phim-super-mario-thien-ha', 'Nối tiếp thành công của phần phim đầu tiên, Mario và Luigi dấn thân vào một cuộc phiêu lưu ngoài sức tưởng tượng khi họ bị cuốn vào không gian sâu thẳm. Lần này, họ gặp gỡ Rosalina, người bảo vệ các vì sao và là "mẹ" của những sinh vật Luma đáng yêu. Cả nhóm phải hợp sức để ngăn chặn âm mưu thôn tính toàn bộ vũ trụ của Bowser, khi hắn đang thu thập các Grand Stars để xây dựng một đế chế thiên hà hùng mạnh. Phim hứa hẹn mang đến những màn rượt đuổi nghẹt thở giữa các hành tinh với trọng lực siêu thực và hình ảnh rực rỡ.', 'Aaron Horvath', 'Chris Pratt, Anya Taylor-Joy, Charlie Day, Jack Black, Donald Glover', 98, '2026-04-03', NULL, 'tmdb_poster_31c1df150ed4eb0e58e2ba85e46b21b3.jpg', 'tmdb_banner_fb423c9cacae51c45ac5147ddbdaef88.jpg', NULL, 'P', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'Nhat Ban'),
(7, 'Quỷ Dữ Từ Luyện Ngục', 'quy-du-tu-luyen-nguc', 'Kingkaew lấy cảm hứng từ vụ án có thật năm 1978, tại nhà tù Bang Kwang khét tiếng. Một người phụ nữ mắc bệnh tâm thần bị buộc tội bắt cóc và sát hại trẻ em gây chấn động. Dù chứng cứ dồn dập, cô vẫn khẳng định “Tôi vô tội”. Cuối cùng, tòa tuyên án tử hình, Kingkaew chết trong oán hận tột cùng. Sau cái chết, hàng loạt hiện tượng kinh hoàng bắt đầu xảy ra. Oan hồn Kingkaew quay lại, gieo rắc nỗi ám ảnh lên tất cả những người liên quan. Khi nỗi sợ dâng cao, họ buộc phải đối mặt với sự thật đen tối phía sau vụ án… và thứ tà ác vẫn chưa chịu ngủ yên.', 'เอกชัย ศรีวิชัย', 'อินทิรา เจริญปุระ, นภัทร อินทร์ใจเอื้อ, อภิญญา สกุลเจริญสุข, พิมพ์พรรณ ชลายนคุปต์, Sonthaya Chitmanee', 101, '2026-04-10', NULL, 'tmdb_poster_32ea29cef3be2a251e5258dab6660a1e.jpg', 'tmdb_banner_4eb920f67a7058df032655c5c545dcd7.jpg', 'https://www.youtube.com/watch?v=KDp0mN0fDOw', 'C13', 'now_showing', 'Tieng Thai', 'Phu de Viet', 'Thai Lan'),
(8, 'Cú Sốc', 'cu-soc', 'Một cặp đôi đang hạnh phúc chuẩn bị kết hôn bất ngờ bị thử thách khi một biến cố ngoài dự kiến khiến cả tuần lễ cưới của họ rơi vào hỗn loạn.', 'Kristoffer Borgli', 'Zendaya, Robert Pattinson, Mamoudou Athie, Alana Haim, Jordyn Curet', 105, '2026-04-10', NULL, 'tmdb_poster_7df6c039b40808ea27251afd3b79a68c.jpg', 'tmdb_banner_58cb9e4cb1591a672d3fa9e599c67491.jpg', NULL, 'C16', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(9, 'Dưới Bóng Điện Hạ', 'duoi-bong-dien-ha', 'Lấy mốc năm 1457 dưới triều đại Joseon, Dưới Bóng Điện Hạ khắc họa số phận nghiệt ngã của vua Danjong - vị quân vương thứ sáu của triều đại (Park Ji-hoon thủ vai). Lên ngôi khi tuổi đời còn non trẻ, Danjong nhanh chóng trở thành quân cờ trong vòng xoáy quyền lực tàn khốc. Bị chính người chú lật đổ, phế truất và đày đến vùng Cheongnyeongpo heo hút, cuộc đời của vị vua trẻ rẽ sang một ngã rẽ đầy u uất. Tại chốn lưu đày, ông gặp trưởng làng Eom Heung Do (Yoo Hai-jin thủ vai) - người đã chủ động biến ngôi làng nghèo thành nơi giam giữ nhà vua, đổi lại hy vọng cứu vãn sinh kế cho dân làng. Từ hai thân phận tưởng chừng đối lập, một cựu đế vương và một thường dân, bộ phim dần hé mở mối liên kết lặng lẽ nhưng sâu sắc - nơi lòng trung thành, sự che chở âm thầm và những phận người nhỏ bé cùng trôi dạt giữa cơn sóng lớn của lịch sử.', '장항준', '유해진, 박지훈, 유지태, 전미도, 김민', 117, '2026-04-10', NULL, 'tmdb_poster_b4a5ae009900cdad8e1d0b334feffb0d.jpg', 'tmdb_banner_cdad5b689025c113e404789494027100.jpg', NULL, 'C13', 'now_showing', 'Tieng Han', 'Phu de Viet', 'Han Quoc'),
(10, 'Ta Khon: Quỷ Đội Lốt Người', 'ta-khon-quy-doi-lot-nguoi', 'Khi ngôi nhà mới được xây trên mảnh đất của thần linh, gia đình Joi đã phải lập tức đối mặt với cơn thịnh nộ của Phi Ta Khon(Quỷ Đội Lốt Người). Để giải cứu chính mình và em gái khỏi lời nguyền nghiệt ngã, Joi quyết tâm lật mở sự thật. Thế nhưng, đằng sau chiếc mặt nạ quỷ lại là một bí mật đen tối mà cậu không bao giờ ngờ tới.', 'Puwadon Naosopa', 'ภาณุวัฒน์ โสประดิษฐ, พลอยปภัส ฝนแก้วศิวพร, Diana Flipo, ธิติ ศรีนวล, Noknoi Uraiporn', 99, '2026-04-10', NULL, 'tmdb_poster_7a5f5d7a4caa587523dd117233bc6c41.jpg', 'tmdb_banner_0e4f97aba9c02805712a74d0411ebeed.jpg', 'https://www.youtube.com/watch?v=4rknH_QUQFw', 'C13', 'now_showing', 'Tieng Thai', 'Phu de Viet', 'Thai Lan'),
(11, 'Sirat: Chuyến Đi Bão Cát', 'sirat-chuyen-di-bao-cat', 'Luis cùng cậu con trai Esteban đang thực hiện chuyến hành trình băng qua miền Nam Morocco. Họ mải miết đi tìm con gái của Luis, người đã mất tích năm tháng sau lần cuối cùng được nhìn thấy tại một lễ hội trên sa mạc. Khi hai cha con rong đuổi từ bữa tiệc này sang bữa tiệc khác, họ nghe phong thanh về một buổi đại nhạc hội rave mang màu sắc huyền thoại gần biên giới Mauritania. Dấn thân vào vùng đất khô cằn trong bối cảnh một cuộc xung đột toàn cầu đang cận kề, Luis và Esteban sớm bị cuốn vào một khung cảnh thiên nhiên nguyên thủy, nơi họ buộc phải bước đi trên sợi dây mong manh giữa thiên đàng và địa ngục.  “Sirāt” là con đường tâm linh thúc đẩy ta "chết trước khi thực sự lìa đời" - giống như những gì xảy đến với nhân vật chính trong bộ phim này. Đó cũng là tên của cây cầu được tương truyền là kết nối giữa địa ngục và thiên đường.', 'Oliver Laxe', 'Sergi López, Bruno Núñez, Stefania Gadda, Joshua Liam Henderson, Richard Bellamy', 115, '2026-04-10', NULL, 'tmdb_poster_aa5455c126cc66eab3bae59213d9de7d.jpg', 'tmdb_banner_e68affd56171105e3b1cc64bc6d9cdcc.jpg', 'https://www.youtube.com/watch?v=i4c1y0a6i4E', 'C16', 'now_showing', 'Tieng Tay Ban Nha', 'Phu de Viet', 'Tay Ban Nha'),
(12, 'Dịch Vụ Giao Hàng của Phù Thủy Kiki', 'dich-vu-giao-hang-cua-phu-thuy-kiki', 'Bộ phim bắt đầu ngay thời điểm Kiki - một cô bé phù thuỷ thực tập - đủ tuổi để rời gia đình và đến một nơi khác, nơi cô phải sống một mình trong vòng một năm để cô có thể trở thành một phù thủy thực thụ. Kiki khởi hành vào buổi tối cùng với sự cổ vũ của mọi người, sử dụng chiếc chổi của mẹ cô, và mang theo chú mèo Jiji cùng một số thứ cần thiết. Kiki chọn thành phố Koriko, một nơi mà cô có thể nhìn thấy biển, một thành phố có chiếc tháp đồng hồ cổ kính. Nhưng với một cô bé 13 tuổi cùng với chiếc chổi bay khắp thành phố thì khó mà có thể tìm được một chỗ để trú thân. Nhờ một lần vô tình giúp đỡ bà chủ tiệm bánh, Kiki đã bắt đầu công việc chuyển phát bằng chiếc chổi bay của mình.', '宮崎駿', '高山みなみ, 佐久間レイ, 山口勝平, 戸田恵子, 信澤三惠子', 103, '2026-04-10', NULL, 'tmdb_poster_b2718f456fa950fd8c918dee018d8055.jpg', 'tmdb_banner_b1ee2dfba631fa0ecbd623b22a4bd037.jpg', NULL, 'P', 'now_showing', 'Tieng Nhat', 'Phu de Viet', 'Nhat Ban'),
(13, 'Phí Phông: Quỷ Máu Rừng Thiêng', 'phi-phong-quy-mau-rung-thieng', 'Phí Phông, loài quỷ khát máu trong truyền thuyết dân gian của đồng bào miền núi gây ám ảnh bao đời nay. Phim xoay quanh Còn (Kiều Minh Tuấn) và Dương (Minh Anh), hai pháp sư tập sự lên núi cứu người mẹ đang bị lời nguyền Phí Phông đánh gục. Cùng lúc đó, trong bản sâu cũng xảy ra nhiều cái chết ghê rợn. Mọi nghi ngờ đổ dồn về hai mẹ con Mon (Diệp Bảo Ngọc) và Lua (Nina Nutthacha), những người mang đặc tính y hệt Phí Phông. Thế nhưng, vẫn còn những bí mật động trời bị chôn vùi trong chốn rừng thiêng nước độc, cuốn hai anh em Còn và Dương vào cuộc truy lùng “Phí Phông” không hồi kết.', 'Đỗ Quốc Trung', 'Kiều Minh Tuấn, ณัฐชา พาโดวัน, Diệp Bảo Ngọc, Trần Gia Huy, Đoàn Minh Anh', 120, '2026-04-16', NULL, 'tmdb_poster_98b6487d5e0fa4b577a513b64c3092fd.jpg', 'tmdb_banner_703159db93e7502d84ca2a3e20e2ca4e.jpg', NULL, 'C13', 'now_showing', 'Tieng Viet', NULL, 'Viet Nam'),
(14, 'Rufus: Thủy Quái Học Bơi', 'rufus-thuy-quai-hoc-boi', '', 'Endre Skandfer', 'Mudit Gupta, Janne Formoe, Torstein Bae, Stig Henrik Hoff, Kåre Conradi', 90, '2026-04-17', NULL, 'tmdb_poster_a18418f1477799d4a17a53b45f831aeb.jpg', 'tmdb_banner_621d4b1188f9c6d1cfc7b8c351d4afda.jpg', NULL, 'C13', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'Norway'),
(15, 'Một bộ phim của Lee Cronin: Xác ướp', 'mot-bo-phim-cua-lee-cronin-xac-uop', 'Con gái nhỏ của một nhà báo biến mất không dấu vết giữa sa mạc. Tám năm sau, gia đình tan vỡ của họ bàng hoàng khi cô bé bất ngờ được đưa trở về — nhưng cuộc đoàn tụ tưởng chừng hạnh phúc nhanh chóng biến thành một cơn ác mộng sống.', 'Lee Cronin', 'Jack Reynor, Laia Costa, May Calamawy, Natalie Grace, Shylo Molina', 133, '2026-04-17', NULL, 'tmdb_poster_8778e7db550c28ff92ffe1989ff309f9.jpg', 'tmdb_banner_b56631fb8ebc33871d3782903ba3a5b2.jpg', NULL, 'C16', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(16, '메소드연기', '', '', '이기혁', '이동휘, 윤경호, 강찬희, 김금순, 윤병희', 93, '2026-04-17', NULL, 'tmdb_poster_6c14382c9818c0bb54b582e0031ad051.jpg', 'tmdb_banner_f8679363191d5526b9fd945b0b526fc8.jpg', NULL, 'C13', 'now_showing', 'Tieng Han', 'Phu de Viet', 'Han Quoc'),
(17, 'Michael', 'michael', 'Michael là bức chân dung điện ảnh khắc họa cuộc đời và di sản của một trong những nghệ sĩ có sức ảnh hưởng lớn nhất mà thế giới từng biết đến. Bộ phim kể về cuộc đời của Michael Jackson ngoài âm nhạc, theo dấu hành trình từ khi tài năng phi thường của ông được phát hiện trong vai trò giọng ca chính của nhóm Jackson Five, cho đến khi ông trở thành một nghệ sĩ có tầm nhìn xa, với khát vọng sáng tạo không ngừng để vươn tới danh hiệu “ngôi sao giải trí vĩ đại nhất thế giới”. Cho thấy cuộc sống phía sau hào quang sân khấu lẫn những màn trình diễn mang tính biểu tượng nhất trong giai đoạn đầu sự nghiệp solo, bộ phim mang đến cho khán giả một góc nhìn chân thực hơn bao giờ hết về Michael Jackson. Đây chính là nơi câu chuyện của ông bắt đầu.', 'Antoine Fuqua', 'Jaafar Jackson, Colman Domingo, Nia Long, Juliano Krue Valdi, Miles Teller', 127, '2026-04-22', NULL, 'tmdb_poster_959fb44129532873160f4c9d8d7044f1.jpg', 'tmdb_banner_ec0bdd260a6f8bd5d71c24010281e945.jpg', 'https://www.youtube.com/watch?v=4k_D-gngvd4', 'C13', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(18, 'Đại Tiệc Trăng Máu 8', 'dai-tiec-trang-mau-8', 'Đại Tiệc Trăng Máu 8 theo chân một vị đạo diễn hay bị coi thường (Vân Sơn đóng) trong dự án thử thách nhất đời ông: thực hiện một bộ phim dài 35 phút chỉ với một cú máy. Hàng loạt tình huống dở khóc dở cười xảy ra khi các diễn viên liên tục gây chuyện “khó đỡ”. Thế nhưng, việc hoàn thành tác phẩm là cơ hội cuối cùng để ông giành lại sự tôn trọng từ cô con gái đam mê nghệ thuật.', 'Phan Gia Nhật Linh', 'Vân Sơn, Lê Khánh, Miu Lê, Liên Bỉnh Phát, Quốc Khánh', 130, '2026-04-23', NULL, 'tmdb_poster_1ad22c94684a3e0c38fd4f128ad9a317.jpg', 'tmdb_banner_4c20aaedd666274b0ae3bf55b6400f90.jpg', 'https://www.youtube.com/watch?v=Nb3agyeJkAo', 'C13', 'now_showing', 'Tieng Viet', NULL, 'Viet Nam'),
(19, 'Heo Năm Móng', 'heo-nam-mong', 'Truyền thuyết Cô Năm Hợi được truyền miệng qua nhiều thế hệ, như một lời nhắc về sự tái sinh đầy nghiệt ngã: linh hồn chết oan hoặc mang nhiều nghiệp quả nên mắc kẹt trong thân xác loài vật, mang theo ký ức và oán lệnh chưa thể hóa giải.  Và giữa những hoa văn Khmer cổ kính và ánh đỏ linh thiêng, Sa - nữ chính của Heo Năm Móng hiện lên như một linh hồn đang đứng giữa hai cõi, như thể hai số phận đang chồng lên nhau.  Liệu Sa còn điều gì vướng mắc ở cõi trần?  Hay chính cô là kẻ từng gây nên tội lỗi, để rồi phải gánh chịu nghiệp báo?', 'Lưu Thành Luân', 'Võ Tấn Phát, Trần Ngọc Vàng, Huỳnh Thanh Thuỷ, Ốc Thanh Vân, Nhật Ý', 103, '2026-04-24', NULL, 'tmdb_poster_81569dd0de512d7c642cbe9d7991a0f0.jpg', 'tmdb_banner_d4394c2531ea0cc59a6fa6c9d2441f66.jpg', 'https://www.youtube.com/watch?v=50b5p3vt85w', 'C13', 'now_showing', 'Tieng Viet', NULL, 'Viet Nam'),
(20, 'Anh Hùng', 'anh-hung', 'Câu chuyện phim theo chân Hùng (Thái Hòa) - người cha đơn thân kiêm tài xế taxi và đồng nghiệp hãng xe là Tuấn (Võ Tấn Phát) bị cuốn vào một phi vụ lừa đảo từ thiện tiền tỉ trong khi sinh mạng cô con gái nhỏ của anh đang nằm gọn trong tay tử thần.', 'Võ Thạch Thảo', 'Thái Hòa, Võ Tấn Phát, Phương Thanh, Đoàn Thế Vinh, Hồng Ánh', 122, '2026-04-24', NULL, 'tmdb_poster_c1cf446fb47e33bc0ce64e6adcca23a7.jpg', 'tmdb_banner_5a024a4019d6dcb98e1a63d909557ec0.jpg', 'https://www.youtube.com/watch?v=9fgmlmYme18', 'C13', 'now_showing', 'Tieng Viet', NULL, 'Viet Nam'),
(21, 'Cá Con Cau Có', 'ca-con-cau-co', '', 'Ricard Cussó', 'Nick Offerman, Nina Oyama, Miranda Otto, Amy Sedaris, Jordin Sparks', 92, '2026-04-24', NULL, 'tmdb_poster_8f45a944d24c398ce68ddeabbd40054f.jpg', 'tmdb_banner_1f1f0a54a3d382ebdd6d0e411bd393ad.jpg', NULL, 'P', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'Uc'),
(22, 'Siêu Quậy Marsupilami', 'sieu-quay-marsupilami', 'Để cứu lấy công việc, David Ticoule chấp nhận vận chuyển một kiện hàng bí ẩn từ Nam Mỹ về Pháp. Anh đưa con trai Léo và vợ cũ Tess đi cùng, vô tình kéo họ vào một phi vụ nguy hiểm mà chính anh cũng chưa kịp hiểu rõ. Mọi thứ nhanh chóng vượt khỏi tầm kiểm soát khi kiện hàng bị mở ra ngoài ý muốn. Bên trong là một sinh vật nhỏ bé, đáng yêu nhưng kéo theo hàng loạt rắc rối không tưởng. Từ một chuyến đi tưởng chừng đơn giản, hành trình trên biển bỗng biến thành chuỗi tình huống dở khóc dở cười. Giữa đại dương, họ phải học cách tin tưởng và sát cánh bên nhau để vượt qua hỗn loạn, đồng thời bảo vệ chính gia đình mình.', 'Philippe Lacheau', 'Philippe Lacheau, Jamel Debbouze, Tarek Boudali, Élodie Fontan, Julien Arruti', 99, '2026-04-24', NULL, 'tmdb_poster_efe58d745b19bcbc37868f3f55fcb992.jpg', 'tmdb_banner_627278d181668cc5e8303d6363ae31b5.jpg', 'https://www.youtube.com/watch?v=0ukgVwmk68o', 'C13', 'now_showing', 'Tieng Phap', 'Phu de Viet', 'Phap'),
(23, 'Yêu Nữ Thích Hàng Hiệu 2', 'yeu-nu-thich-hang-hieu-2', 'Hai mươi năm sau màn hóa thân kinh điển vào các vai diễn Miranda, Andy, Emily và Nigel — Meryl Streep, Anne Hathaway, Emily Blunt và Stanley Tucci sẽ chính thức trở lại với những con phố thời thượng của New York và văn phòng sang trọng của Tạp chí Runway trong "The Devil Wears Prada 2" (Yêu Nữ Thích Hàng Hiệu 2). Đây là phần phim tiếp theo cực kỳ được mong đợi từ 20th Century Studios, kế thừa sức hút từ hiện tượng điện ảnh năm 2006 từng định hình phong cách cho cả một thế hệ. Bộ phim được đạo diễn bởi David Frankel, kịch bản bởi Aline Brosh McKenna, sản xuất bởi Wendy Finerman, điều hành sản xuất bởi Michael Bederman, Karen Rosenfelt và Aline Brosh McKenna.', 'David Frankel', 'Meryl Streep, Anne Hathaway, Emily Blunt, Stanley Tucci, Justin Theroux', 119, '2026-04-30', NULL, 'tmdb_poster_3f3581d0450d5167b4d25dbc14d6ad1b.jpg', 'tmdb_banner_43408a8598e05e60cab36aea2bcfb476.jpg', 'https://www.youtube.com/watch?v=ZS77vl5hLpg', 'C13', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(24, 'Mumbo: Giải Cứu Bé Bự', 'mumbo-giai-cuu-be-bu', '', 'Karsten Kiilerich', 'Victor Spanning, Annevig Schelde Ebbe, Kirsten Lehfeldt, Rebecca Rønde Kiilerich, Asger Reher', 80, '2026-04-30', NULL, 'tmdb_poster_c4abc0ff45a3df5dd3ae3208e4fb3126.jpg', 'tmdb_banner_0e386bddbea91904ea905bc7e316f056.jpg', NULL, 'C13', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'Denmark'),
(25, '熊出没·年年有熊', '-1', '', 'Huida Lin', 'Zhang Bingjun, Zhang Wei, Tan Xiao', 90, '2026-05-01', NULL, 'tmdb_poster_5f44de580466dbf4dcd9c8a519e38c85.jpg', 'tmdb_banner_9088c8620d37bb8988be08621d63d485.jpg', NULL, 'C13', 'now_showing', 'Tieng Trung', 'Phu de Viet', 'Trung Quoc'),
(26, 'Phi Vụ Thanh Toán Hào Môn', 'phi-vu-thanh-toan-hao-mon', 'Bị gia đình siêu giàu ruồng bỏ ngay từ khi chào đời, Becket Redfellow — một gã lao động chân tay — sẵn sàng làm mọi thứ để giành lại phần thừa kế của mình, bất chấp phải loại bỏ bao nhiêu người thân đang đứng chắn đường.', 'John Patton Ford', 'Glen Powell, Margaret Qualley, Jessica Henwick, Bill Camp, Zach Woods', 105, '2026-05-01', NULL, 'tmdb_poster_50be79c8de227629b0486a91b43aff0e.jpg', 'tmdb_banner_c520ca30441b82a4ca56ce8f0a81e466.jpg', NULL, 'C16', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'Anh'),
(27, 'Thẩm Mỹ Viện Âm Phủ', 'tham-my-vien-am-phu', 'Khi cái đẹp trở thành nỗi ám ảnh.  Để cứu người yêu đang hôn mê, Thanh chấp nhận làm việc tại một thẩm mỹ viện hẻo lánh. Nhưng nơi đây nhanh chóng biến thành cơn ác mộng với những nghi lễ ma quái, những hồn ma vất vưởng và một bí mật kinh hoàng phía sau vẻ hào nhoáng.  Khi bị cuốn vào nghi lễ “đi thiếp”, Thanh phải đối diện lựa chọn sinh tử: ở lại cõi âm bên người mình yêu, hay chiến đấu để thoát khỏi thế lực hắc ám.', 'Nguyễn Hữu Hoàng', 'Ngọc Trinh, Xuân Lan, Lê Xuân Tiền, Khazsak, Rima Thanh Vy', 100, '2026-05-08', NULL, 'tmdb_poster_19c3104997fdeb54e45d7ae23cdc9ca0.jpg', 'tmdb_banner_508e3e5ea55c63788741d3b44c01539b.jpg', NULL, 'C13', 'now_showing', 'Tieng Viet', NULL, 'Viet Nam'),
(28, 'Đội Thám Tử Cừu: Án Mạng Lúc Nửa Đêm', 'doi-tham-tu-cuu-an-mang-luc-nua-dem', 'Trong bộ phim trinh thám hài hước, độc đáo này, George (Hugh Jackman) là một người chăn cừu, mỗi tối đều đọc tiểu thuyết trinh thám cho đàn cừu yêu quý nghe, nghĩ rằng chúng không thể hiểu được. Nhưng khi George bất ngờ qua đời trong một sự cố bí ẩn trên trang trại, đàn cừu quyết định tự mình trở thành thám tử. Lần theo manh mối và điều tra các nghi phạm là con người, chúng chứng minh rằng ngay cả cừu cũng có thể phá án xuất sắc.', 'Kyle Balda', 'Hugh Jackman, Julia Louis-Dreyfus, Emma Thompson, Nicholas Braun, Nicholas Galitzine', 109, '2026-05-08', NULL, 'tmdb_poster_47fdee4427e14c168de90db5d336f239.jpg', 'tmdb_banner_ea94c000ec5138bcdb372efcb15f30b2.jpg', 'https://www.youtube.com/watch?v=z3cJl_rdQCw', 'P', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(29, 'Phổi Sắt', 'phoi-sat', 'Một đại dương máu. Hy vọng cuối cùng còn sót lại sau Đại Tận Diệt Lặng Im. Trong những hành lang rỉ sét của các trạm không gian đang sụp đổ, tàn dư cuối cùng của nhân loại chế tạo một chiếc tàu ngầm để thăm dò những tầng sâu đang chảy máu… và hàn kín một linh hồn bên trong để điều khiển nó. Nhưng hy vọng nơi hư vô này mong manh chẳng khác gì ánh sao xa xôi. Đây không phải một chuyến thám hiểm. Đây là một bản án tử hình.', 'Mark Fischbach', 'Mark Fischbach, Caroline Kaplan, Troy Baker, Elsie Lovelock, Elle LaMont', 125, '2026-05-08', NULL, 'tmdb_poster_f90f100394029d0b498677407a5140f4.jpg', 'tmdb_banner_f277e0343aebf5436975efbfe308e36d.jpg', NULL, 'C16', 'now_showing', 'Tieng Anh', 'Phu de Viet', 'My'),
(30, 'Một Thời Ta Đã Yêu', 'mot-thoi-ta-da-yeu', 'Bộ phim này là một thước phim sâu sắc về mọi hình thái của tình yêu. Chạm ngưỡng trưởng thành, một chàng trai 18 tuổi dấn thân vào hành trình định nghĩa lại tình yêu: tình yêu không chỉ được viết bằng đam mê, mà còn bằng những hy sinh thầm lặng. Từ tình yêu đôi lứa, tình thân gia đình đến sự gắn kết bạn bè.', 'Nguyễn Xuân Nghĩa', 'Quỳnh Thy, Quốc Trường, Quốc Huy, Lê Khanh, Thành Lộc', 119, '2026-05-15', NULL, 'tmdb_poster_5f8771c0674684685dd6411fd1f019dc.jpg', 'tmdb_banner_064588eb1d40f31b39fce1f7392869b1.jpg', NULL, 'C13', 'coming_soon', 'Tieng Viet', NULL, 'Viet Nam'),
(31, 'Tạm Biệt Gohan', 'tam-biet-gohan', 'Suốt mười năm đằng đẵng, chú chó hoang lông trắng với chiếc mũi đỏ mang tên \'GOHAN\' cứ thế phiêu dạt giữa cuộc đời, ôm trọn những ký ức chẳng thể phai nhòa.